/**
 * Recipe to convert V1 enum constants written in pascal case to their V2 screaming snake case equivalents.
 *
 * <p>
 * This recipe assumes the enclosing type has already been changed to its V2 equivalent (e.g. by {@link ChangeSdkType}) and
 * therefore only rewrites references to V2 enum types.
 */
@SdkInternalApi
public class EnumCasingToV2 extends Recipe {

    private static Set<String> ENUMS = new HashSet<>();

    @Override
    public String getDisplayName() {
        return "V1 Enum Casing to V2";
    }

    @Override
    public String getDescription() {
        return "Transforms V1 enum constants from pascal case to screaming snake case for v2.";
    }

    @Override
    public TreeVisitor<?, ExecutionContext> getVisitor() {
        return new Visitor();
    }

    private static String v2Casing(String enumName) {
        enumName = enumName.replaceAll("textORcsv", "TEXT_OR_CSV");
        enumName = String.join("_", CodegenNamingUtils.splitOnWordBoundaries(enumName));
        return StringUtils.upperCase(enumName);
    }

    private static class Visitor extends JavaIsoVisitor<ExecutionContext> {

        @Override
        public J.FieldAccess visitFieldAccess(J.FieldAccess fieldAccess, ExecutionContext ctx) {
            fieldAccess = super.visitFieldAccess(fieldAccess, ctx);

            if (isV2EnumValue(fieldAccess)) {
                String v2Name = v2Casing(fieldAccess.getSimpleName());
                ENUMS.add(v2Name);
                return fieldAccess.withName(fieldAccess.getName().withSimpleName(v2Name));
            }
            return fieldAccess;
        }

        @Override
        public J.Identifier visitIdentifier(J.Identifier identifier, ExecutionContext ctx) {
            identifier = super.visitIdentifier(identifier, ctx);

            if (ENUMS.contains(identifier.getSimpleName())) {
                return identifier.withFieldType(identifier.getFieldType().withName(identifier.getSimpleName()));
            }
            return identifier;
        }

        public boolean isV2EnumValue(J.FieldAccess fieldAccess) {
            JavaType type = fieldAccess.getTarget().getType();
            JavaType.FullyQualified fullyQualified = TypeUtils.asFullyQualified(type);
            if (fullyQualified == null) {
                return false;
            }
            return isV2ModelClass(type) && fullyQualified.getKind() == JavaType.FullyQualified.Kind.Enum;
        }
    }
